import { setTimeout as sleep } from 'node:timers/promises';

export async function retry(fn, { retries = 4, base = 200, cap = 5000, signal } = {}) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn({ attempt, signal });
    } catch (err) {
      if (attempt >= retries || err.retryable === false) throw err;
      const delay = Math.random() * Math.min(cap, base * 2 ** attempt); // full jitter
      await sleep(delay, undefined, { signal });
    }
  }
}

export class LRU {
  #max; #map = new Map();
  constructor(max = 500) { this.#max = max; }
  get(key) {
    if (!this.#map.has(key)) return undefined;
    const v = this.#map.get(key);
    this.#map.delete(key);
    this.#map.set(key, v); // mark as most recent
    return v;
  }
  set(key, value) {
    this.#map.delete(key);
    this.#map.set(key, value);
    if (this.#map.size > this.#max) this.#map.delete(this.#map.keys().next().value);
  }
}

export function tokenBucket({ capacity, refillPerSec }) {
  const buckets = new Map();
  return (key, now = Date.now()) => {
    const b = buckets.get(key) ?? { tokens: capacity, ts: now };
    b.tokens = Math.min(capacity, b.tokens + ((now - b.ts) / 1000) * refillPerSec);
    b.ts = now;
    const allowed = b.tokens >= 1;
    if (allowed) b.tokens -= 1;
    buckets.set(key, b);
    return { allowed, remaining: Math.floor(b.tokens) };
  };
}

