export function idempotent(store) {
  return async (req, res, next) => {
    const key = req.get('idempotency-key');
    if (!key) return res.status(400).json({ title: 'Idempotency-Key header required' });
    const fingerprint = req.method + ' ' + req.originalUrl + ' ' + JSON.stringify(req.body);
    const saved = await store.get(key);
    if (saved) {
      if (saved.fingerprint !== fingerprint) return res.status(422).json({ title: 'Key reused with a different request' });
      if (saved.status === 'in_progress') return res.status(409).json({ title: 'Request in progress' });
      return res.status(saved.code).json(saved.body);
    }
    if (!(await store.begin(key, fingerprint))) return res.status(409).json({ title: 'Request in progress' }); // atomic: SET NX or unique insert
    const send = res.json.bind(res);
    res.json = (body) => { store.finish(key, res.statusCode, body).catch(console.error); return send(body); };
    next();
  };
}

